"""Render measured V30/V31 results after independent audits; no model changes."""
from pathlib import Path
import json
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
ROOT=Path(__file__).resolve().parent
D30=ROOT/'experiments/v30_structured_response/analysis';D31=ROOT/'experiments/v31_guide_response/analysis'

def write(path,text):path.write_bytes((text.rstrip()+'\n').encode())

def main():
 a=json.loads((D30/'mean_screen.json').read_text());b=json.loads((D31/'mean_screen.json').read_text());stress=json.loads((D30/'target_holdout/results.json').read_text())
 for path in [D30/'independent_audit.json',D30/'target_holdout/independent_audit.json',D31/'independent_audit.json']:assert json.loads(path.read_text())['passed']
 assert not a['new_mean_candidate_passes'] and not b['new_candidate_passes']
 lines=['# V30 full-target structured response results','', '**Decision: no V30 release.** V24 remains the best published project entry at 0.142997855. The full-target and construct-aware means failed the frozen screen; no generated counts, private scoring, fresh reserve or package followed.','', '## Across-context mean screen','', '|Variant|LFC MSE ratio to held-family V24|LFC MAE ratio|','|---|---:|---:|']
 for name in ['string_full','string_panel','random_full','construct_full']:
  v=a['summary'][name];lines.append(f"|{name}|{v['mse_ratio']:.9f}|{v['mae_ratio']:.9f}|")
 lines+=['','Full STRING reduces squared error 0.67%, but randomized embeddings reduce it 0.71%. Both primary candidates miss the required 1% MSE and 0.5% MAE improvements and fail to beat the randomized control. They beat panel-only training by a very small amount. Construct-aware pooling changes the result negligibly at this precision. No statistical-equivalence claim is made.','', '|Family|Full STRING MSE ratio|Randomized MSE ratio|','|---|---:|---:|']
 for family in ['H1','Orion','CD4']:
  f=next(r for r in a['records'] if r['stage']=='outer' and r['outer']==family and r['variant']=='string_full');r=next(r for r in a['records'] if r['stage']=='outer' and r['outer']==family and r['variant']=='random_full');lines.append(f"|{family}|{f['mse_ratio']:.9f}|{r['mse_ratio']:.9f}|")
 lines+=['','There are 31 active source/variant fits and one explicit RPE1 panel-only abstention; each active source fit has four rank/penalty solutions. The frozen nested selection records 96 inner family/configuration comparisons and 12 outer variant comparisons. These are summary-response tests on reused public biology, not independent biological replications or private anchor-scaled metrics. Whole-Orion and whole-CD4 exclusions are enforced.','', '## Separate unseen-target stress test','', '|Source|STRING MSE ratio to fitting-target mean|Randomized MSE ratio|Held targets|','|---|---:|---:|---:|']
 for source in ['K562_full','RPE1_full']:
  x=next(r for r in stress['records'] if r['source']==source and r['variant']=='string');y=next(r for r in stress['records'] if r['source']==source and r['variant']=='random');lines.append(f"|{source}|{x['test']['mse_vs_constant']:.9f}|{y['test']['mse_vs_constant']:.9f}|{x['test']['targets']}|")
 lines+=['','STRING learns useful unseen-target signal within a measured source: squared-error reductions are 1.66% in K562 and 7.90% in RPE1 relative to the fitting-target mean. Randomized embeddings do not improve that baseline. This is a different task from predicting a new cell context. It cannot rescue the failed cross-context release candidate.','', 'The target test was separately frozen after H1 context results were visible, before any target-stress outcomes. A target-identity hash creates 60/20/20 fitting/inner/test partitions; choose rank/penalty on inner only, refit 80%, then score 20% once. Fitting means, target sets and saved predictions are independently replayed. The secondary versus-zero diagnostic reproduces the original whole-vector float32 dot product; primary versus-constant errors use float64.','', '## Verification and scope','', 'Independent original-row reconstructions match ten K562/RPE1 target summaries exactly. Five representative source/variant audits verify the masked-loss gradient, explicit abstention and saved predictions; full saved prediction replays have zero error. The worst checked relative masked-gradient residual is below 7e-9. Nested choices and actual excluded-family model requests pass. The separate target stress audit checks all four models, disjoint target roles, fitted bias and prediction arithmetic. Two solver fixtures pass, including equivalence to an independently constructed masked least-squares system.','', 'This result applies to the implemented source-specific linear response bases, STRING features and rank-weighted transfer. It does not rule out nonlinear context-conditioned mean learning, conditional transport or foundation-model fine-tuning. Guide-resolved work is separately recorded in [V31_RESULTS.md](V31_RESULTS.md).','', 'Reproduction: [V30_STRATEGY.md](V30_STRATEGY.md), root `collect_v30_embeddings.py`, `run_v30_experiment.py`, `run_v30_target_holdout.py`, `audit_v30_experiment.py`, `audit_v30_target_holdout.py`. The target stress outcomes are locked; use its auditor to verify an existing run rather than reopening selection. Large arrays remain outside Git.']
 write(ROOT/'V30_RESULTS.md','\n'.join(lines));write(ROOT/'V30_SUBMISSION.md','# V30 artifact decision\n\nNo V30 submission was created. Both mean candidates failed the frozen requirements; preserve V24. See V30_RESULTS.md. No new generated population, reserve access or upload occurred.')
 alpha=b['alpha'];lines=['# V31 guide-resolved response results','', '**Decision: no V31 release.** Guide-aware means failed the frozen screen. V24 remains the best published project entry at 0.142997855; no generated counts, fresh donor reserve or package were opened.','', f'Whole-guide-held-out calibration within public D2 selected correction strength {alpha}. There are 86 held-guide cases evaluated at three strengths (258 calibration rows), not 258 independent biological experiments. After minimum-cell filters, 22 resting and 21 stimulated targets support multiple eligible guides;34 targets are represented per condition.','', '## Mean-only development','', '|Arm|All-study LFC MSE ratio|D1 donor LFC MSE ratio|D1 donor CPM MSE ratio|','|---|---:|---:|---:|']
 for arm in ['guide','pooled','guide_shuffled','target_shuffled']:
  z=b['summary'][arm];d=b['study_summary'][arm]['CD4_D1'];lines.append(f"|{arm}|{z['mse_ratio']:.9f}|{d['mse_ratio']:.9f}|{d['cpm_mse_ratio']:.9f}|")
 lines+=['', 'Guide-aware transfer reduces D1 squared fold-change error 1.14% and mean-CPM squared error 3.58%. Ordinary pooled responses and shuffled guide labels do slightly better. It beats target-shuffled fingerprints, supporting some useful target-specific donor response information, but does not establish a benefit from separating guide effects. The all-study fold-change error improvement is only 0.38%.','', 'H1 and Orion mean profiles remain exactly at baseline because the compatibility gate is 0. The D1 donor gate is 1. These are fallback/noninferiority checks on H1/Orion, not successful guide-response generalization to those lineages.','', 'Failed checks: overall squared/absolute fold-change gains, the required 5% donor squared-error gain, and beating pooled/guide-shuffled controls. Worst-family noninferiority, mean-CPM noninferiority and beating target shuffle pass. Diagnostic pooled/shuffled arms are not promoted after the sole guide candidate fails.','', 'The 36 development cases include 28 genuine 400-cell H1/Orion cases and eight 200-cell D1 donor cases. Four arms give 144 deterministic mean comparisons; **no synthetic cell populations were generated**. Repeated seeds reuse the same biological contrasts. These approximate clipped/smoothed mean errors are not official Wilcoxon/anchor-scaled scores.','', '## Validation boundary and verification','', 'The raw teacher uses D2 resting/stimulated cells only. D1 validation excludes every CD4 summary from the baseline, then adds only raw-D2 guide-derived information. This is a donor-transfer test within an existing study, not a whole-CD4 or unseen-lineage holdout. D2 stimulated cells are not validation. The untouched D3 reserve was not accessed.','', 'Three guide-pooling invariants pass. Independent dense raw-count calculations reconstruct selected source guide means, knockdown proxies, lane-control variances, hierarchical effects and confidence. Held-guide roles, selected strength and study-level arithmetic are recomputed; route/source-family exclusion and own-gene preservation are checked. Detailed measured tolerances are archived in the independent audit.','', 'The wider conditional-transport and full transition fine-tuning proposals remain untrained. The staged plans require a useful mean finalist before those larger downstream runs; these rejected mean pilots do not demonstrate that those model classes fail.','', 'Reproduction and exact assumptions: [V31_STRATEGY.md](V31_STRATEGY.md), root `v31_methods.py`, `run_v31_experiment.py`, `test_v31_guides.py`, `audit_v31_experiment.py`. Prior frozen models and V24 package are unchanged.']
 write(ROOT/'V31_RESULTS.md','\n'.join(lines));write(ROOT/'V31_SUBMISSION.md','# V31 artifact decision\n\nNo V31 submission was created. The guide-aware candidate fails its frozen mean requirements and does not beat pooled or guide-shuffled controls. Preserve V24; no new reserve access or upload. See V31_RESULTS.md.')
 fig,axs=plt.subplots(1,3,figsize=(15,4.6));labels=['Full STRING','Panel-only','Random embedding','Construct-aware'];vals=[100*(1-a['summary'][n]['mse_ratio']) for n in ['string_full','string_panel','random_full','construct_full']];axs[0].barh(labels,vals,color=['#2563eb','#94a3b8','#f59e0b','#0f766e']);axs[0].invert_yaxis();axs[0].set_title('Across contexts\nrelative to held-family V24');axs[0].set_xlabel('Squared LFC error reduction (%)')
 for i,v in enumerate(vals):axs[0].text(v+.015,i,f'{v:.2f}%',va='center',fontsize=9)
 names=[];vals=[]
 for source in ['K562_full','RPE1_full']:
  for variant in ['string','random']:
   rec=next(r for r in stress['records'] if r['source']==source and r['variant']==variant);names.append(source.replace('_full','')+' / '+variant);vals.append(100*(1-rec['test']['mse_vs_constant']))
 axs[1].barh(names,vals,color=['#2563eb','#f59e0b']*2);axs[1].invert_yaxis();axs[1].set_title('Unseen targets within a source\nrelative to fitting-target mean');axs[1].set_xlabel('Squared LFC error reduction (%)')
 for i,v in enumerate(vals):axs[1].text(v+.15,i,f'{v:.2f}%',va='center',fontsize=9)
 labels=['Guide-aware','Pooled','Guide shuffle','Target shuffle'];vals=[100*(1-b['study_summary'][n]['CD4_D1']['mse_ratio']) for n in ['guide','pooled','guide_shuffled','target_shuffled']];axs[2].barh(labels,vals,color=['#2563eb','#94a3b8','#f59e0b','#cbd5e1']);axs[2].invert_yaxis();axs[2].set_title('CD4 donor transfer\nrelative to CD4-free V24 reference');axs[2].set_xlabel('Squared LFC error reduction (%)')
 for i,v in enumerate(vals):axs[2].text(v+.02,i,f'{v:.2f}%',va='center',fontsize=9)
 for ax in axs:ax.axvline(0,color='#334155',linewidth=.8);ax.grid(axis='x',alpha=.2);ax.set_axisbelow(True);ax.spines[['top','right']].set_visible(False);lo,hi=ax.get_xlim();ax.set_xlim(lo,hi*1.2)
 fig.suptitle('V30/V31 public mean tests: useful source signal, insufficient transfer gains',fontsize=13);fig.text(.5,.005,'Different baselines across panels. Mean-only diagnostics; no official leaderboard score or generated-cell performance.',ha='center',fontsize=9);fig.tight_layout(rect=[0,.045,1,.92]);fig.savefig(D30/'v30_v31_comparison.png',dpi=170);plt.close(fig);print('Wrote audited V30/V31 reports and comparison figure.')
if __name__=='__main__':main()
